4: /**
5:  * Petshop_Fulfillment v1.6.1
6:  *
7:  * v1.6.1 (2026-08-20): `own_stock` PAŠALINTAS iš `_stock` šaltinių sąrašo.
8:  *
9:  *   PRIEŽASTIS: S590 architektūroje (petshop-katalogas.php:919, av-stock,
10:  *   av-limit, av-reduce) `_own_stock_qty` yra ATSKIRAS AV sandėlio kiekis,
11:  *   gyvenantis ŠALIA `_stock`:
12:  *     - `_stock`          = tiekėjo kiekis (ZB/VF sync jį perrašo)
13:  *     - `_own_stock_qty`  = AV lentynos kiekis (S477: jo rašymas neliečia _stock)
14:  *     - rodymui juos sudeda Petshop_AV_Limit (3 sluoksnis)
15:  *     - nusirašymą pagal _ps_source atskiria petshop-av-reduce
16:  *   Senoji v1.3–v1.5 logika `_own_stock_qty` laikė `_stock` šaltiniu su
17:  *   aukščiausia pirmenybe — dvigubai prekei tai arba perrašydavo tiekėjo
18:  *   kiekį savu, arba (kartu su AV_Limit) skaičiuodavo AV du kartus.
19:  *   Matavimas 2026-08-20: prekių su dviem šaltiniais buvo 0, todėl elgsenos
20:  *   pakeitimas esamam katalogui = 0 prekių.
21:  *
22:  *   update_own_stock() paliktas suderinamumui: rašo meta ir perskaičiuoja,
23:  *   bet `_stock` nuo šiol atspindi tik tiekėjus.
24:  *
25:  * v1.5.0 (2026-06-05): pridėtas VF dropship sluoksnis + update_vf_qty().
26:  * v1.3 (paveldėta): set_wc_stock() naudoja wc_update_product_stock('set').
27:  */
28: class Petshop_Fulfillment {
29: 
30:     /**
31:      * TIEKĖJŲ pirmenybės sąrašas (top-down). AV sandėlio čia NĖRA (v1.6.1) —
32:      * AV kiekį prie rodomo likučio prideda Petshop_AV_Limit.
33:      */
34:     private array $suppliers = [
35:         'zb_dropship' => '_zb_qty',
36:         'vf_dropship' => '_vf_qty',
37:         // 'supplier_4' => '_s4_qty',
38:     ];
39: 
40:     /**
41:      * Perskaičiuoja WC likutį (TIEKĖJO) ir active_fulfillment_source.
42:      */
43:     public function recalculate( int $post_id ): string {
44:         $quantities = $this->get_all_quantities( $post_id );
45: 
46:         foreach ( $this->suppliers as $source_key => $meta_key ) {
47:             $qty = (int) ( $quantities[ $source_key ] ?? 0 );
48:             if ( $qty > 0 ) {
49:                 $this->set_wc_stock( $post_id, $qty, $source_key );
50:                 return $source_key;
51:             }
52:         }
53: 
54:         $this->set_wc_stock( $post_id, 0, 'out_of_stock' );
55:         return 'out_of_stock';
56:     }
57: 
58:     public function get_all_quantities( int $post_id ): array {
59:         $result = [];
60:         foreach ( $this->suppliers as $source_key => $meta_key ) {
61:             $result[ $source_key ] = (int) get_post_meta( $post_id, $meta_key, true );
62:         }
63:         return $result;
64:     }
65: 
66:     /**
67:      * Nustato WC likutį.
68:      * wc_update_product_stock($id, $qty, 'set') — ne rankinis _stock rašymas (fix #1).
69:      */
70:     private function set_wc_stock( int $post_id, int $qty, string $source ): void {
71:         update_post_meta( $post_id, '_manage_stock', 'yes' );
72:         update_post_meta( $post_id, '_active_fulfillment_source', $source );
73:         wc_update_product_stock( $post_id, $qty, 'set' );
74:     }
75: 
76:     public function update_zb_qty( int $post_id, int $qty ): void {
77:         update_post_meta( $post_id, '_zb_qty', $qty );
78:         $this->recalculate( $post_id );
79:     }
80: 
81:     public function update_vf_qty( int $post_id, int $qty ): void {
82:         update_post_meta( $post_id, '_vf_qty', $qty );
83:         $this->recalculate( $post_id );
84:     }
85: 
86:     /**
87:      * v1.6.1: rašo AV meta (suderinamumui), bet `_stock` skaičiuojamas
88:      * tik iš tiekėjų — AV kiekį rodymui prideda Petshop_AV_Limit.
89:      */
90:     public function update_own_stock( int $post_id, int $qty ): void {
91:         update_post_meta( $post_id, '_own_stock_qty', $qty );
92:         $this->recalculate( $post_id );
93:     }
94: 
95:     public function get_active_source( int $post_id ): string {
96:         return (string) get_post_meta( $post_id, '_active_fulfillment_source', true ) ?: 'unknown';
97:     }
98: 
99:     public function get_suppliers(): array { return $this->suppliers; }
100: }
